<span class="line">        <span class="token function">removeBuffEffects</span><span class="token punctuation">(</span>playerId<span class="token punctuation">,</span> buff<span class="token operator">-&gt;</span>buffId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
